def rightShift(s, i, j):
	s = list(s)
	while j > i:
		(s[j], s[j - 1]) = (s[j - 1], s[j])
		j -= 1
	return ''.join(s)

def leftShift(s, i, j):
	s = list(s)
	while j > i:
		(s[i], s[i + 1]) = (s[i + 1], s[i])
		i += 1
	return ''.join(s)

def solution():
	N = int(input())
	S = input()
	ans = S
	for i in range(N):
		for j in range(N):
			ls = leftShift(S, i, j)
			rs = rightShift(S, i, j)
			ans = min(ans, rs, ls)
	print(ans)
T = int(input())
while T > 0:
	T = T - 1
	solution()
